// Generated from original Python AST, not a copied Rust algorithm.
use bson::{Bson, Document};
use quantnight_task_core::create_generate::{
    generation_begin_plan, generation_failure_status, generation_finish_plan, GenerationErrorKind,
};
use serde_json::Value;
fn document(v: &Value) -> Document {
    Bson::try_from(v.clone())
        .unwrap()
        .as_document()
        .unwrap()
        .clone()
}
#[test]
fn original_generation_state_queries_and_failure_classification_match() {
    let cases: Vec<Value> = serde_json::from_str(GOLDEN).unwrap();
    for (i, c) in cases.iter().enumerate() {
        let op = c["op"].as_str().unwrap();
        if op == "classification" {
            let kind = match c["kind"].as_str().unwrap() {
                "ordinary" => GenerationErrorKind::Ordinary,
                "timeout" => GenerationErrorKind::Timeout,
                "database_uncertain" => GenerationErrorKind::DatabaseUncertain,
                _ => GenerationErrorKind::Interrupted,
            };
            let total = c["total"].as_str().map(|s| s.parse::<u64>().unwrap());
            assert_eq!(
                generation_failure_status(&kind, total),
                c["expected"].as_str().unwrap(),
                "case {i}"
            );
            continue;
        }
        let task = document(&c["task"]);
        let actual = if op == "begin" {
            generation_begin_plan(&task, TOKEN, c["phase"].as_str().unwrap(), 321, STAMP)
        } else {
            generation_finish_plan(
                &task,
                TOKEN,
                c["status"].as_str().unwrap(),
                document(&c["fields"]),
                STAMP,
            )
        };
        if let Some(error) = c["expected"].get("error") {
            assert_eq!(
                actual,
                Err(error.as_str().unwrap().to_owned()),
                "case {i}: {c}"
            );
        } else {
            assert_eq!(
                actual,
                Ok((
                    document(&c["expected"]["query"]),
                    document(&c["expected"]["update"])
                )),
                "case {i}: {c}"
            );
        }
    }
}
